// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1000 ether);
        vm.deal(address(this), amount);
        (bool sentFunding, ) = address(c).call{value: amount}("");
        assertTrue(sentFunding);

        c.withdrawAll();

        assertTrue(address(c).balance == 0);
    }
}
